import sys

def rob_brute(nums):
    n = len(nums)
    if n == 0: return 0
    best = 0
    for mask in range(1 << n):
        ok = True
        s = 0
        for i in range(n):
            if mask & (1 << i):
                if i + 1 < n and mask & (1 << (i + 1)):
                    ok = False; break
                s += nums[i]
        if ok and s > best: best = s
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(rob_brute(nums))

import sys

def rob_best(nums):
    prev, cur = 0, 0
    for x in nums:
        prev, cur = cur, max(cur, prev + x)
    return cur

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(rob_best(nums))
